    "/us/en/acute-care/c/the-science-behind-support-surfaces": { "template": "tier2-landing-page", "metadata": { "title": "The Science Behind Support Surfaces Registration", "pageTitle": "The Science Behind Support Surfaces Registration", "description": "Stryker in partnership with Becker\u2019s Health Review are presenting an on-demand webinar focusing on the utilization of support surfaces technology for prevention and treatment of pressure injuries. ", "image": "/content/dam/stryker/acute-care/campaigns/the-science-behind-support-surfaces/science-behind-support-surfaces.png", "imageAlt": "The Science Behind Support Surfaces", "tags": ["stryker:custom/acute-care"], "originallyPublished": "2023-02-06T14:53:27.000Z", "lastPublished": "2026-08-13T20:02:51.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "1315", "afterSubmitAction": "redirectToPage", "message": null, "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/acute-care/c/the-science-behind-support-surfaces/webinar": { "template": "tier2-landing-page", "metadata": { "title": "The Science Behind Support Surfaces Webinar", "pageTitle": "The Science Behind Support Surfaces Webinar", "description": "Thank you for registering for The Science Behind Support Surfaces virtual webinar.  ", "image": null, "imageAlt": null, "tags": ["stryker:custom/acute-care"], "originallyPublished": null, "lastPublished": "2023-09-14T14:20:23.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
