    "/us/en/emergency-care/c/iacp-2023": { "template": "tier2-landing-page", "metadata": { "title": "IACP", "pageTitle": null, "description": null, "image": null, "imageAlt": null, "tags": [], "originallyPublished": null, "lastPublished": "2023-07-05T18:55:09.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2804", "afterSubmitAction": "showMessage", "message": "Thanks!", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/emergency-care/c/naemsp-2023-annual-meeting": { "template": "tier2-landing-page", "metadata": { "title": "NAEMSP 2023 Annual Meeting", "pageTitle": "NAEMSP 2023 Annual Meeting ", "description": "You work in one of the world\u2019s most demanding, fast-paced environments. You need durable, powerful connected devices to help save lives and coordinate teams to deliver the highest quality of care. We are excited to get to know you better and work with you to help you deliver the best care possible. ", "image": "/content/dam/stryker/ems/tradeshows/images/NAEMSP-header.jpg", "imageAlt": "NAEMSP 2023 Annual Meeting", "tags": ["stryker:business-unit/ems"], "originallyPublished": null, "lastPublished": "2023-01-19T18:25:18.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2804", "afterSubmitAction": "showMessage", "message": "Thanks!", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
