    "/us/en/smart-care/c/smart-hospitals-connecting-people-and-technology": { "template": "tier2-landing-page", "metadata": { "title": "Smart hospitals connecting people and technology", "pageTitle": "Smart hospitals connecting people and technology", "description": "The SmartHospital Platform reimagines care delivery and transforms facilities into a connected digital ecosystem. It brings together people, processes and technology to support real-time workflow adaptation.", "image": "/content/dam/stryker/acute-care/images/gold-adh-wave_1200x680.jpg", "imageAlt": "Abstract digital wave with dots and lines in a gold gradient", "tags": [], "originallyPublished": "2026-02-12T19:36:45.000Z", "lastPublished": "2026-07-17T20:29:54.000Z", "contentID": "AC-GSNPS-SYK-2604250_REV-0_en_us" }, "anchors": [{ "id": "overview", "title": "Overview", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "related", "title": "Related", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "contact", "title": "Contact", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }], "disclaimer": "<p>*Prioritized alarm notifications require Engage Medical Device Alarm Notification (EMDAN), FDA 510(k)-cleared middleware.</p>", "forms": [{ "formId": "2761", "afterSubmitAction": "showMessage", "message": "Thank you for your interest. A Stryker representative will reach out to you shortly.", "useProduction": true }], "tabs": [["Product Information"]], "cardLists": [{ "component": "customizable", "title": "Related", "items": [{ "path": "/us/en/smart-care/news/2025-smart-hospital-summit", "resolved": true, "title": "Inside Stryker\u2019s Smart Hospital Summit 2025", "description": "At Stryker's 2025 Smart Hospital Summit, healthcare leaders gathered to collaborate and drive digital transformation across healthcare.", "image": "/content/dam/stryker/acute-care/news/smart-hospital-summit/smart-hospital-summit-session_1440x816.jpg", "alt": "Smart Hospital Summit Session" }, { "path": "/us/en/smart-care/news/enhancing-hospital-communication-patient-family-satisfaction", "resolved": true, "title": "Enhancing hospital communication for patient and family satisfaction", "description": "The hospital experience can be stressful for patients and families. When a patient is undergoing a procedure, timely communication with patients and families helps relieve the anxiety of waiting and wondering.", "image": "/content/dam/stryker/acute-care/news/ease-sase-study-feb-2025/ac-newsroom_ease-case-study-app-screen_1200x680.jpg", "alt": "Mobile screen showing patient texting on EASE app" }, { "path": "/us/en/smart-care/news/enabling-smart-connected-care-with-careai", "resolved": true, "title": "Transforming care delivery with AI: how the care.ai SmartCare platform is enabling smart, connected care", "description": "Empowering care team members with AI-enabled virtual care and ambient monitoring solutions.", "image": "/content/dam/stryker/acute-care/news/care-ai/care-ai-video-unit_1440x816.jpg", "alt": "care.ai smart patient room sensor" }, { "path": "/us/en/smart-care/news/successful-virtual-care-partnership-in-hospitals", "resolved": true, "title": "Virtual care at scale: Henry Ford Health\u2019s journey to enterprise-wide transformation", "description": "Learn how Henry Ford Health created a virtual care model with care.ai to enhance workflow efficiency, improve patient care and support safety in their hospitals.", "image": "/content/dam/stryker/acute-care/news/care-ai-x-sonifi-x-henry-ford-success-story/care-ai-sensor_screen_1440x816.jpg", "alt": "Patient interacting with clinical using Care.ai sensor, nurse in background" }] }], "missingAlt": [] },
    "/us/en/smart-care/training-and-education": { "template": "tier2-landing-page", "metadata": { "title": "Smart Care training and education", "pageTitle": "Smart Care training and education", "description": "On-demand webinars, online and in-person training and additional resources created specifically for clinical education. ", "image": "/content/dam/stryker/smart-care/training-and-education/images/Smart-Care_TE_Hero-Moble_v1.jpg", "imageAlt": "smiling nurse with ipad", "tags": [], "originallyPublished": "2024-06-07T16:03:05.000Z", "lastPublished": "2026-02-11T15:16:50.000Z", "contentID": null }, "anchors": [{ "id": "webinars", "title": "Webinars", "hidden": false, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "contact", "title": "Contact", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "products", "title": "products", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }], "disclaimer": null, "forms": [{ "formId": "4644", "afterSubmitAction": "showMessage", "message": "Thank you for your interest in Smart Care Training and Education. A Stryker representative will reach out to you shortly.", "useProduction": true }], "tabs": [], "cardLists": [{ "component": "customizable_copy_co", "title": "Featured products", "items": [{ "path": "/us/en/smart-care/products/sync-badge", "resolved": true, "title": "Sync Badge", "description": "Inspired by nurses and designed for fast, reliable collaboration and enhanced workflow efficiency", "image": "/content/dam/stryker/acute-care/products/sync-badge/images/sync-badge-thumbnail_1200x680.jpg", "alt": "Sync Badge" }, { "path": "/us/en/smart-care/products/vocera-smartbadge", "resolved": true, "title": "Vocera Smartbadge", "description": "Simplify hospital communication and workflow to help improve staff safety and impact on patient care.", "image": "/content/dam/stryker/acute-care/products/vocera-smartbadge/images/vocera-smartbadge_screen_v1.jpg", "alt": "smartbadgescreenoff" }, { "path": "/us/en/acute-care/products/vocera-engage", "resolved": false }] }, { "component": "customizable_copy", "title": null, "items": [{ "path": "/us/en/smart-care/products/virtual-nursing", "resolved": true, "title": "Virtual Nursing", "description": "Virtual nurses work from a virtual command center supporting a curated task list, which can allow bedside clinical team more time to focus on hands-on patient care.", "image": "/content/dam/stryker/acute-care/products/care-ai/images/virtual-nursing/Virtual Nursing_Product_Hero_732x488.jpg", "alt": "Virtual nursing screen showing patient and virtual nurse communication" }, { "path": "/us/en/smart-care/products/virtual-monitoring", "resolved": true, "title": "Virtual Monitoring", "description": "Scale virtual sitter resources by performing workflows like patient monitoring and night rounding through a virtual model.", "image": "/content/dam/stryker/acute-care/products/care-ai/images/virtual-monitoring/care.ai Virtual Monitoring_Hero_Image_732x488_DRAFT-v1.jpg", "alt": "A screenshot of a virtual sitter's screen for patient monitoring" }, { "path": "/us/en/smart-care/products/ambient-monitoring", "resolved": true, "title": "Ambient Monitoring", "description": "Powered by AI-driven, always-aware ambient monitoring sensors, our integrated, cloud-based solutions enhance and automate clinical and operational workflows.", "image": "/content/dam/stryker/acute-care/products/care-ai/images/ambient-monitoring_1200x680.jpg", "alt": "Ambient monitoring video logic representation in patient room" }] }], "missingAlt": [] },
